def page_path(slug, lang):
    file = "index.html" if slug == "home" else f"{slug}.html"
    return file if lang == "en" else f"es/{file}"

def href(slug, lang, fragment=""):
    return ("index.html" if slug == "home" else f"{slug}.html") + fragment

def asset(name, lang):
    return ("../" if lang == "es" else "") + name

def alternate(slug, lang):
    file = "index.html" if slug == "home" else f"{slug}.html"
    return f"es/{file}" if lang == "en" else f"../{file}"

def esc(value):
    return html.escape(value, quote=True)

def head(slug, lang, title, description, schema=None):
    en = f"{SITE}/{page_path(slug, 'en')}".replace("/index.html", "/")
    es = f"{SITE}/{page_path(slug, 'es')}".replace("/index.html", "/")
    current = en if lang == "en" else es
    structured = f'<script type="application/ld+json">{json.dumps(schema, ensure_ascii=False)}</script>' if schema else ""
    preload = f'<link rel="preload" as="image" href="{asset("img/lineup-800.webp",lang)}" media="(max-width:700px)"><link rel="preload" as="image" href="{asset("img/lineup.webp",lang)}" media="(min-width:701px)">' if slug=="home" else ""
    return f'''<!doctype html><html lang="{lang}"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#21366b">
<meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{current}"><meta property="og:image" content="{SITE}/img/lineup.webp"><meta property="og:locale" content="{'en_US' if lang=='en' else 'es_419'}">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(description)}"><meta name="twitter:image" content="{SITE}/img/lineup.webp">
<link rel="canonical" href="{current}"><link rel="alternate" hreflang="en" href="{en}"><link rel="alternate" hreflang="es" href="{es}"><link rel="alternate" hreflang="x-default" href="{en}">
<link rel="icon" href="{asset('favicon.svg', lang)}" type="image/svg+xml">{preload}<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<script>document.documentElement.classList.add("js")</script><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700;800&amp;family=Nunito:wght@800;900&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="{asset('site.css', lang)}">{structured}</head>'''

def header(slug, lang):
    t = ({"products":"Products","recipes":"Recipes","where-to-buy":"Where to buy","about":"Our brand","partners":"For partners","skip":"Skip to content","menu":"Open menu","search":"Search products","nav":"Main navigation"} if lang == "en" else {"products":"Productos","recipes":"Recetas","where-to-buy":"Dónde comprar","about":"Nuestra marca","partners":"Para socios","skip":"Saltar al contenido","menu":"Abrir menú","search":"Buscar productos","nav":"Navegación principal"})
    nav = "".join(f'<a href="{href(key,lang)}"'+(' aria-current="page"' if slug == key else '')+f'>{t[key]}</a>' for key in ("products","recipes","where-to-buy","about","partners"))
    en_link=href(slug,lang) if lang=="en" else alternate(slug,lang); es_link=alternate(slug,lang) if lang=="en" else href(slug,lang)
    return f'''<body><a class="skip-link" href="#main">{t['skip']}</a><header class="site-header"><div class="header-inner">
<a class="brand-mark" href="{href('home',lang)}" aria-label="ami anytime home"><img src="{asset('img/new-lockup.webp',lang)}" width="860" height="612" alt="ami anytime"></a>
<nav class="primary-nav" id="primary-nav" aria-label="{t['nav']}">{nav}</nav><div class="header-tools"><div class="language-switch" aria-label="Language"><a href="{en_link}"{' aria-current="page"' if lang=='en' else ''} lang="en">EN</a><a href="{es_link}"{' aria-current="page"' if lang=='es' else ''} lang="es">ES</a></div><a class="search-link" href="{href('products',lang)}#catalog" aria-label="{t['search']}">{SEARCH}</a><button class="menu-toggle" type="button" aria-controls="primary-nav" aria-expanded="false" aria-label="{t['menu']}">{MENU}</button></div></div></header>'''

def footer(lang):
    if lang == "en":
        line="Everyday products. One familiar brand. Always with you."
        cols=[("Explore",[("Products","products",""),("Recipes","recipes",""),("Where to buy","where-to-buy","")]),("About ami",[("Our brand","about",""),("For partners","partners","")]),("Help",[("Product support","about","#product-support"),("Contact us","contact","")])]
        legal="ami anytime™ is an American Foods International brand. Trademark applications are pending in selected jurisdictions."
    else:
        line="Productos de todos los días. Una marca fácil de reconocer. Siempre contigo."
        cols=[("Explora",[("Productos","products",""),("Recetas","recipes",""),("Dónde comprar","where-to-buy","")]),("Sobre ami",[("Nuestra marca","about",""),("Para socios","partners","")]),("Ayuda",[("Ayuda con un producto","about","#product-support"),("Contáctanos","contact","")])]
        legal="ami anytime™ es una marca de American Foods International. Las solicitudes de registro están en trámite en determinadas jurisdicciones."
    blocks="".join(f'<div><h2>{heading}</h2><ul class="footer-links">'+"".join(f'<li><a href="{href(slug,lang,fragment)}">{label}</a></li>' for label,slug,fragment in items)+"</ul></div>" for heading,items in cols)
    return f'''<footer class="site-footer"><div class="footer-inner"><div class="footer-grid"><div class="footer-brand"><div class="footer-wordmark">ami<span>.</span><sup>™</sup></div><p>{line}</p></div>{blocks}</div><div class="footer-bottom"><span>© 2026 American Foods International</span><span>{legal}</span></div></div></footer><script src="{asset('site.js',lang)}" defer></script></body></html>'''

def product_card(product, lang, linked=False, quick=False):
    image,en,es,size,category=product; name=en if lang=="en" else es; cat=CATEGORIES[category][0 if lang=="en" else 1]
    if quick:
        tag="button"
        attrs=f''' type="button" data-quick-product data-name="{esc(name)}" data-image="{asset('img/'+image,lang)}" data-size="{esc(size)}" data-category-label="{esc(cat)}" data-full="{href('product-tomato-paste',lang) if en=='Tomato Paste' else ''}" aria-label="{'View' if lang=='en' else 'Ver'} ami {esc(name)}"'''
    elif linked:
        tag="a"
        target=href("product-tomato-paste",lang) if en=="Tomato Paste" else f'''{href("products",lang)}?q={quote(name)}#catalog'''
        attrs=f' href="{target}"'
    else:
        tag="article"; attrs=""
    action=("Quick view" if lang=="en" else "Vista rápida") if quick else ("View product" if lang=="en" else "Ver producto")
    action_html=f'<span class="product-card-action">{action} {ARROW}</span>' if quick or linked else ""
    return f'''<{tag} class="product-card"{attrs} data-product="{esc(en+' '+es+' '+size)}" data-category="{category}" style="--category:{CATEGORIES[category][2]}"><div class="product-visual"><img src="{asset('img/'+image,lang)}" width="900" height="900" alt="{esc('ami '+name+', '+size)}" loading="lazy"></div><div class="product-meta"><span class="product-category">{cat}</span><strong class="product-name">{name}</strong><span class="product-card-bottom"><span class="product-size">{size}</span>{action_html}</span></div></{tag}>'''

def recipe_card(image,name,time,uses,anchor,lang):
    prep="Prep" if lang=="en" else "Preparación"; serves="Serves 4" if lang=="en" else "Rinde 4 porciones"
    width,height=IMAGE_SIZES[image]
    return f'''<a class="recipe-card" href="{href('recipes',lang)}#{anchor}"><img src="{asset('img/'+image,lang)}" width="{width}" height="{height}" alt="{esc(name)}" loading="lazy"><div class="recipe-card-body"><span class="eyebrow">{prep}: {time}</span><h3>{name}</h3><div class="recipe-meta"><span>{serves}</span></div><div class="uses">{"".join(f'<span>{esc(x)}</span>' for x in uses)}</div></div></a>'''

def frame(slug,lang,title,description,main,schema=None):
    return "\n".join((head(slug,lang,title,description,schema),header(slug,lang),main,footer(lang)))

def organization(lang):
    return {"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":f"{SITE}/#website","name":"ami anytime","url":SITE+("/" if lang=="en" else "/es/"),"publisher":{"@id":"https://www.americanfoodsllc.com/#organization"},"about":{"@id":f"{SITE}/#brand"}},{"@type":"Brand","@id":f"{SITE}/#brand","name":"ami anytime","logo":f"{SITE}/img/new-lockup.webp"},{"@type":"Organization","@id":"https://www.americanfoodsllc.com/#organization","name":"American Foods International","url":"https://www.americanfoodsllc.com/","logo":f"{SITE}/img/afi-logo-navy.png"}]}

def afi_panel(lang, compact=False):
    en=lang=="en"
    title="The company behind ami" if en else "La compañía detrás de ami"
    body=("ami is built by American Foods International, a Miami-based food distributor working with retailers, restaurants and hotels across the United States, Latin America, the Caribbean and Asia. AFI connects international sourcing, consolidation, documentation, labeling and private-label development in one cross-border platform." if en else "ami es desarrollada por American Foods International, una distribuidora de alimentos con sede en Miami que trabaja con cadenas, restaurantes y hoteles en Estados Unidos, Latinoamérica, el Caribe y Asia. AFI reúne abastecimiento internacional, consolidación, documentación, etiquetado y desarrollo de marcas propias en una sola plataforma transfronteriza.")
    facts=(("Miami + Panama","Commercial and operating teams"),("From plant to shelf","Sourcing, export and launch support"),("Built for growth","Programs that scale by market and category")) if en else (("Miami + Panamá","Equipos comerciales y operativos"),("De la planta al anaquel","Abastecimiento, exportación y lanzamiento"),("Creada para crecer","Programas que avanzan por mercado y categoría"))
    classes="afi-panel compact" if compact else "afi-panel"
    return f'''<section class="{classes}" data-reveal><div class="afi-brand"><img src="{asset('img/afi-logo-white.png',lang)}" width="3491" height="1119" alt="American Foods — We Take Brands Global" loading="lazy"><span>{'Owner and operating platform' if en else 'Propietaria y plataforma operativa'}</span></div><div class="afi-copy"><span class="eyebrow light">American Foods International</span><h2>{title}</h2><p>{body}</p><div class="afi-facts">{"".join(f'<div><strong>{h}</strong><span>{p}</span></div>' for h,p in facts)}</div><a class="button light" href="https://www.americanfoodsllc.com/">{'Meet American Foods' if en else 'Conoce American Foods'} {ARROW}</a></div></section>'''

